import { test } from "node:test";
import assert from "node:assert/strict";
import { add, clamp } from "../src/math.mjs";

test("add still works", () => {
  assert.equal(add(2, 3), 5);
});

test("clamp limits to the inclusive range", () => {
  assert.equal(clamp(5, 1, 10), 5);
  assert.equal(clamp(-3, 1, 10), 1);
  assert.equal(clamp(99, 1, 10), 10);
  assert.equal(clamp(1, 1, 10), 1);
  assert.equal(clamp(10, 1, 10), 10);
});

test("clamp rejects an inverted range", () => {
  assert.throws(() => clamp(5, 10, 1), RangeError);
});
